// word-frequency (java entry) -- count 3,000,000 picks from a 64-word
// vocabulary generated by a pinned integer LCG, then fold the counts into one
// deterministic checksum.
//
// Same workload and same output in every language entry. This is the
// hash-map-shaped task: every pick is a string-keyed lookup + increment, and
// the final fold walks the vocabulary in a fixed order so no language's map
// iteration order can leak into the output.

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

public class Main {
    private static final int CORPUS = 3_000_000;
    private static final int VOCAB = 64;
    private static final long MOD = 1_000_000_007L;

    public static void main(String[] args) {
        String[] words = new String[VOCAB];
        for (int i = 0; i < VOCAB; i++) {
            words[i] = String.format(Locale.ROOT, "word%02d", i);
        }

        Map<String, Integer> counts = new HashMap<>();
        long state = 1;
        for (int pick = 0; pick < CORPUS; pick++) {
            state = (state * 48271) % 2147483647L;
            String word = words[(int) (state % VOCAB)];
            Integer current = counts.get(word);
            counts.put(word, current == null ? 1 : current + 1);
        }

        long checksum = 0;
        for (int i = 0; i < VOCAB; i++) {
            int count = counts.getOrDefault(words[i], 0);
            checksum = (checksum * 31 + count) % MOD;
        }
        System.out.println(checksum);
    }
}
